import{c as s,U as i,j as n,g as t,o as l,a6 as o,n as r}from"./chunks/framework.h4W4t1IS.js";const m=JSON.parse('{"title":"Cloner un dépôt de code","description":"","frontmatter":{"title":"Cloner un dépôt de code","status":"ready","tags":["git","git-base","all"],"authors":["Jean-François Dion"],"reviewers":[]},"headers":[],"relativePath":"git/clone.md","filePath":"git/clone.md"}'),p={name:"git/clone.md"},d={id:"frontmatter-title",tabindex:"-1"};function c(a,e,u,h,g,k){return i(),n("div",null,[t("h1",d,[l(o(a.$frontmatter.title)+" ",1),e[0]||(e[0]=t("a",{class:"header-anchor",href:"#frontmatter-title","aria-label":'Permalink to "{{ $frontmatter.title }}"'},"​",-1))]),e[1]||(e[1]=r(`<p>Cloner un dépôt est le point de départ de tout travail avec Git. Pour chaque exercice ou travail pratique, nous partirons d&#39;un dépôt Git.</p><h2 id="objectifs-d-apprentissage" tabindex="-1">Objectifs d&#39;apprentissage <a class="header-anchor" href="#objectifs-d-apprentissage" aria-label="Permalink to &quot;Objectifs d&#39;apprentissage&quot;">​</a></h2><div class="info custom-block"><p class="custom-block-title">Après cette section, tu seras capable de...</p><ul><li>Expliquer la distinction entre un <a href="/420-w30-sf-po2/lexique.html#depot-distant" class="lexicon-link" title="Dépôt Git hébergé sur un serveur distant, permettant la collaboration et le partage de code entre plusieurs développeurs.">dépôt distant</a> et un dépôt local</li><li>Cloner un dépôt de code fourni pour un travail pratique</li></ul></div><h2 id="depot-distant-vs-depot-local" tabindex="-1">Dépôt distant vs dépôt local <a class="header-anchor" href="#depot-distant-vs-depot-local" aria-label="Permalink to &quot;Dépôt distant vs dépôt local&quot;">​</a></h2><p>Le <strong>dépôt distant</strong> vit sur un serveur (ex. GitHub) : c&#39;est la copie de référence, partagée entre les membres de l&#39;équipe. Le <strong>dépôt local</strong> vit sur ton poste : c&#39;est la copie de travail où tu développes et commits. Cloner un dépôt distant crée une copie locale complète (historique inclus) et établit automatiquement le lien entre les deux.</p><h2 id="depots-crees-a-l-avance" tabindex="-1">Dépôts créés à l&#39;avance <a class="header-anchor" href="#depots-crees-a-l-avance" aria-label="Permalink to &quot;Dépôts créés à l&#39;avance&quot;">​</a></h2><p>Pour chaque travail pratique, ton dépôt est <strong>déjà créé</strong> pour toi (et ton équipe, le cas échéant) sur GitHub avant le début du TP. Tu n&#39;as qu&#39;à cloner le dépôt pour ton travail.</p><div class="tip custom-block"><p class="custom-block-title">Travail en équipe</p><p>Si tu es en équipe, le dépôt distant est unique et partagé - les deux équipiers y ont accès. Chaque membre clone le dépôt indépendamment sur son propre poste ; ce sont les branches qui permettent ensuite de travailler en parallèle sans se nuire.</p></div><h2 id="cloner-le-depot" tabindex="-1">Cloner le dépôt <a class="header-anchor" href="#cloner-le-depot" aria-label="Permalink to &quot;Cloner le dépôt&quot;">​</a></h2><ol><li>Sur la page GitHub du dépôt, cliquer sur le bouton vert <strong>Code</strong></li><li>Copier l&#39;URL HTTPS proposée</li><li>Dans un terminal, se positionner dans le dossier où tu ranges tes projets, puis cloner :</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/po2-jfd-{session}/{nom-du-depot}.git</span></span></code></pre></div><ol start="4"><li>Se déplacer dans le dossier créé :</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> nom-du-depot</span></span></code></pre></div><p>Vérifie que le remote <code>origin</code> pointe bien vers le dépôt distant :</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> remote</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -v</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># origin  https://github.com/nom-organisation/nom-du-depot.git (fetch)</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># origin  https://github.com/nom-organisation/nom-du-depot.git (push)</span></span></code></pre></div><h2 id="verifier-l-etat-du-depot" tabindex="-1">Vérifier l&#39;état du dépôt <a class="header-anchor" href="#verifier-l-etat-du-depot" aria-label="Permalink to &quot;Vérifier l&#39;état du dépôt&quot;">​</a></h2><p>Une fois le projet ouvert, confirme que tout est en ordre avec quelques commandes de base :</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> status</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> log</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --oneline</span></span></code></pre></div><p>Le dépôt cloné est prêt : tu peux maintenant créer tes branches de travail (voir la section suivante) et commencer le développement.</p>`,19))])}const v=s(p,[["render",c]]);export{m as __pageData,v as default};
